@interface TCEGenerate:UIViewController
@property UITextView *input;
@property UILabel *message;
@property UIButton *generate;
@property TCEAIJob *job;
@property(copy)void(^created)(NSDictionary *);
@end
@implementation TCEGenerate
- (void)viewDidLoad{[super viewDidLoad];self.title=@"AI 生成卡片";self.view.backgroundColor=TIOPaper();self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;
 UIScrollView *scroll=[UIScrollView new];scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];[NSLayoutConstraint activateConstraints:@[[scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.keyboardLayoutGuide.topAnchor],[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor]]];
 UILabel *intro=[UILabel new];intro.text=@"说说你想看什么\n例如：一张专注卡，显示今天读书30分钟，目标60分钟，带书本图标和进度条。";intro.font=[UIFont systemFontOfSize:17];intro.textColor=TIOInk();intro.numberOfLines=0;
 _input=[UITextView new];_input.font=[UIFont systemFontOfSize:17];_input.backgroundColor=[UIColor colorWithWhite:.15 alpha:1];_input.textColor=TIOInk();_input.layer.cornerRadius=16;_input.textContainerInset=UIEdgeInsetsMake(14,12,14,12);[_input.heightAnchor constraintEqualToConstant:160].active=YES;_input.accessibilityLabel=@"描述卡片需求";
 _generate=[UIButton buttonWithType:UIButtonTypeSystem];[_generate setTitle:@"生成可编辑预览" forState:UIControlStateNormal];TIOStyleAction(_generate,YES,NO);[_generate.heightAnchor constraintEqualToConstant:50].active=YES;[_generate addTarget:self action:@selector(run) forControlEvents:UIControlEventTouchUpInside];
 _message=[UILabel new];_message.text=@"复用「模型与对话」中的自定义模型。仅发送本次描述与组件约束，不发送聊天记录、图标原图或账户数据。生成内容是静态草稿，不能查询实时额度；不会自动发送到眼镜。";_message.textColor=UIColor.secondaryLabelColor;_message.font=[UIFont systemFontOfSize:14];_message.numberOfLines=0;
 UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[intro,_input,_generate,_message]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=20;stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:20],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-24],[stack.leadingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.trailingAnchor constant:-20]]];}
- (void)run{if(_job){[_job cancel];_job=nil;_message.text=@"已取消，未创建草稿。";[_generate setTitle:@"生成可编辑预览" forState:UIControlStateNormal];return;}[self.view endEditing:YES];_job=[TCEAIJob new];__weak typeof(self) weak=self;_job.status=^(NSString *s){weak.message.text=s;};_job.complete=^(NSDictionary *d,NSString *error){typeof(self) s=weak;if(!s)return;s.job=nil;[s.generate setTitle:@"生成可编辑预览" forState:UIControlStateNormal];NSString *why=nil;if(d&&!TCEEncode(d,&why)){s.message.text=why;return;}if(!d){s.message.text=error;return;}s.message.text=@"校验通过 · 请检查示例数值及排版";if(s.created)s.created(d);};[_generate setTitle:@"取消生成" forState:UIControlStateNormal];[_job start:_input.text];}
- (void)viewDidDisappear:(BOOL)a{[super viewDidDisappear:a];if(self.isMovingFromParentViewController||!self.navigationController){[_job cancel];_job=nil;}}
- (void)dealloc{[_job cancel];}
@end
@interface TCETemplates:UITableViewController
