@end
@implementation TCETemplates
- (void)viewDidLoad{[super viewDidLoad];self.title=@"新建卡片";TIOStyleResearchTable(self);self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=270;NSMutableArray *a=[NSMutableArray new];for(NSUInteger i=0;i<TCETemplateNames().count;i++)[a addObject:TCETemplate(i,[NSString stringWithFormat:@"turbo_ui_card_preview%lu",(unsigned long)i])];_templates=a;}
