- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return s?@"选择模板 · 所见即所得":@"从一句话开始";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p{UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];TIOStyleResearchCell(c);c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;if(!p.section){c.textLabel.text=@"用 AI 设计";c.detailTextLabel.text=@"描述需求，生成后还可拖动修改";c.imageView.image=[UIImage systemImageNamed:@"sparkles"];return c;}
 TCECanvas *preview=[TCECanvas new];preview.draft=_templates[p.row];preview.userInteractionEnabled=NO;UILabel *title=[UILabel new];title.text=TCETemplateNames()[p.row];title.textColor=TIOInk();title.font=[UIFont systemFontOfSize:17 weight:UIFontWeightSemibold];UILabel *subtitle=[UILabel new];subtitle.text=[NSString stringWithFormat:@"%lu 个组件 · 点选使用 · 示例数据",(unsigned long)[_templates[p.row][@"components"]count]];subtitle.textColor=UIColor.secondaryLabelColor;subtitle.font=[UIFont systemFontOfSize:12];
 UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[preview,title,subtitle]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=10;stack.translatesAutoresizingMaskIntoConstraints=NO;[c.contentView addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:c.contentView.leadingAnchor constant:16],[stack.trailingAnchor constraintEqualToAnchor:c.contentView.trailingAnchor constant:-16],[stack.topAnchor constraintEqualToAnchor:c.contentView.topAnchor constant:16],[stack.bottomAnchor constraintEqualToAnchor:c.contentView.bottomAnchor constant:-16],[preview.heightAnchor constraintEqualToAnchor:preview.widthAnchor multiplier:194.0/256]]];return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p{[t deselectRowAtIndexPath:p animated:YES];if(!p.section){TCEGenerate *g=[TCEGenerate new];g.created=_chosen;[self.navigationController pushViewController:g animated:YES];return;}NSMutableDictionary *d=[_templates[p.row]mutableCopy];d[@"id"]=[@"turbo_ui_card_"stringByAppendingString:[[NSUUID.UUID.UUIDString stringByReplacingOccurrencesOfString:@"-" withString:@""]lowercaseString]];if(_chosen)_chosen(d);}
@end
@interface TCELibrary:UITableViewController
@property NSArray *drafts;
@end
@implementation TCELibrary
- (void)viewDidLoad{[super viewDidLoad];self.title=@"仪表盘";TIOStyleResearchTable(self);self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=330;self.navigationItem.rightBarButtonItems=@[[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(create)],[[UIBarButtonItem alloc]initWithTitle:@"数据源" style:UIBarButtonItemStylePlain target:self action:@selector(backend)]];}
- (void)backend{[self.navigationController pushViewController:TCEBackendController() animated:YES];}
- (void)viewWillAppear:(BOOL)a{[super viewWillAppear:a];_drafts=Load();[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)v numberOfRowsInSection:(NSInteger)s{return MAX(_drafts.count,1);}
- (NSString *)tableView:(UITableView *)v titleForFooterInSection:(NSInteger)s{return @"TCE1 · 选择模板，拖动组件，裁剪自己的图标。\n最多 8 张本机草稿；仅配置快照，不自动联网。手机预览可用，发送需要配套 TCE1 固件。";}
- (UITableViewCell *)tableView:(UITableView *)v cellForRowAtIndexPath:(NSIndexPath *)p{
 UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];TIOStyleResearchCell(c);
 NSDictionary *d=_drafts.count?_drafts[p.row]:TCETemplate(0,@"turbo_ui_card_empty");
 TCECanvas *preview=[TCECanvas new];preview.draft=d;preview.userInteractionEnabled=NO;preview.accessibilityIdentifier=@"dashboard-list-preview";
 UILabel *title=[UILabel new];title.text=_drafts.count?d[@"name"]:@"创建第一张卡片";title.textColor=TIOInk();title.font=[UIFont systemFontOfSize:17 weight:UIFontWeightSemibold];title.numberOfLines=2;
 UILabel *note=[UILabel new];note.text=_drafts.count?[NSString stringWithFormat:@"%lu 个组件 · 本机草稿 · 点按编辑",(unsigned long)[d[@"components"]count]]:@"模板效果示例 · 点按选择模板或用 AI 创建";note.textColor=UIColor.secondaryLabelColor;note.font=[UIFont systemFontOfSize:12];note.numberOfLines=0;
 UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[preview,title,note]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=10;stack.translatesAutoresizingMaskIntoConstraints=NO;[c.contentView addSubview:stack];
 [NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:c.contentView.leadingAnchor constant:16],[stack.trailingAnchor constraintEqualToAnchor:c.contentView.trailingAnchor constant:-16],[stack.topAnchor constraintEqualToAnchor:c.contentView.topAnchor constant:16],[stack.bottomAnchor constraintEqualToAnchor:c.contentView.bottomAnchor constant:-16],[preview.heightAnchor constraintEqualToAnchor:preview.widthAnchor multiplier:194.0/256]]];
 c.accessibilityLabel=[NSString stringWithFormat:@"%@，%@",title.text,note.text];return c;
}
- (void)open:(NSDictionary *)d{TCEEditor *e=[TCEEditor new];e.draft=d;[self.navigationController pushViewController:e animated:YES];}
- (void)tableView:(UITableView *)v didSelectRowAtIndexPath:(NSIndexPath *)p{[v deselectRowAtIndexPath:p animated:YES];if(_drafts.count)[self open:_drafts[p.row]];else[self create];}
- (void)create{if(Load().count>=8){Alert(self,@"草稿已满",@"左滑移除不需要的手机草稿，不影响眼镜上的卡片。");return;}TCETemplates *t=[[TCETemplates alloc]initWithStyle:UITableViewStyleInsetGrouped];__weak typeof(self) weak=self;t.chosen=^(NSDictionary *d){typeof(self) s=weak;if(!s)return;if(!Save(d)){Alert(s.navigationController.topViewController,@"无法保存",@"请检查草稿数量或布局限制。");return;}[s.navigationController popToViewController:s animated:NO];[s open:d];};[self.navigationController pushViewController:t animated:YES];}
- (BOOL)tableView:(UITableView *)v canEditRowAtIndexPath:(NSIndexPath *)p{return _drafts.count>0;}
- (void)tableView:(UITableView *)v commitEditingStyle:(UITableViewCellEditingStyle)s forRowAtIndexPath:(NSIndexPath *)p{if(s!=UITableViewCellEditingStyleDelete)return;NSDictionary *target=_drafts[p.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:@"删除本机草稿？" message:@"不会删除眼镜上的卡片。需要移除眼镜卡片时请先在编辑页操作。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"删除草稿" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){NSMutableArray *all=[Load()mutableCopy];[all removeObject:target];[NSUserDefaults.standardUserDefaults setObject:[NSJSONSerialization dataWithJSONObject:all options:0 error:nil] forKey:StoreKey];self.drafts=all;[self.tableView reloadData];}]];[self presentViewController:a animated:YES completion:nil];}
@end
UIViewController *TCEEditorController(void){return [[TCELibrary alloc]initWithStyle:UITableViewStyleInsetGrouped];}
